package com.nuvio.app.desktop

import com.nuvio.app.desktop.mpv.MpvPlayer
import kotlin.test.Test
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Measures the software render path with a synthetic video generated by mpv (lavfi testsrc2):
 * frames delivered per second at 1080p60 and 4K60. Run only on demand:
 * -Pnuvio.desktop.benchmark=true (it needs a few seconds per resolution).
 */
class MpvRenderBenchmarkTest {
    private val enabled = System.getProperty("nuvio.desktop.benchmark") == "true"

    @Test
    fun softwareRenderThroughput() {
        if (!enabled) return
        listOf(1920 to 1080, 3840 to 2160).forEach { (width, height) ->
            val player = assertNotNull(MpvPlayer.create(), "libmpv not available")
            try {
                player.setTargetSize(width, height)
                player.load("av://lavfi:testsrc2=size=${width}x$height:rate=60", null, emptyMap(), null) {}
                player.setProperty("pause", "no")
                Thread.sleep(2_000) // warm-up
                val startFrames = player.frameNumber()
                val startedAt = System.nanoTime()
                Thread.sleep(5_000)
                val frames = player.frameNumber() - startFrames
                val seconds = (System.nanoTime() - startedAt) / 1e9
                val fps = frames / seconds
                println("BENCHMARK ${width}x$height: ${"%.1f".format(fps)} fps rendered (target 60), dropped=${player.getProperty("frame-drop-count")}, decoder-drops=${player.getProperty("decoder-frame-drop-count")}")
                assertTrue(frames > 0, "no frame rendered at ${width}x$height")
            } finally {
                player.release()
            }
        }
    }
}
